  let DOMESTIC_PROVIDERS = null;
  const DOMESTIC_BUCKET_CACHE = new Map();

  function ensureDomesticProviders() {
    if (!DOMESTIC_PROVIDERS) DOMESTIC_PROVIDERS = DOMESTIC_PROVIDER_SOURCE.split("|");
    return DOMESTIC_PROVIDERS;
  }

  function getDomesticBucket(first) {
    if (DOMESTIC_BUCKET_CACHE.has(first)) return DOMESTIC_BUCKET_CACHE.get(first);
    const bucket = new Map();
    const packed = DOMESTIC_RANGE_SOURCE[first] || "";
    for (const token of packed.split(";")) {
      if (!token) continue;
      const [spanRaw, providerRaw] = token.split(":");
      const providerId = Number(providerRaw);
      if (!Number.isInteger(providerId)) continue;
      const [startRaw, endRaw = startRaw] = spanRaw.split("-");
      const start = Number(startRaw);
      const end = Number(endRaw);
      if (!Number.isInteger(start) || !Number.isInteger(end)) continue;
      for (let second = start; second <= end; second += 1) bucket.set(second, providerId);
    }
    DOMESTIC_BUCKET_CACHE.set(first, bucket);
    return bucket;
  }

  function getDomesticProviderId(prefix) {
    const [firstRaw, secondRaw] = String(prefix || "").split(".");
    const first = Number(firstRaw);
    const second = Number(secondRaw);
    if (!Number.isInteger(first) || !Number.isInteger(second)) return -1;
    const providerId = getDomesticBucket(first).get(second);
    return Number.isInteger(providerId) ? providerId : -1;
  }

  function getDomesticNetwork(prefix) {
    const providerId = getDomesticProviderId(prefix);
    if (providerId < 0) return null;
    const providers = ensureDomesticProviders();
    return {
      provider: providers[providerId] || "정보없음",
      kind: DOMESTIC_KIND_SOURCE[providerId] === "1" ? "mobile" : "wired"
    };
  }

